// Rebuild: serve docs/ on port 8765 (python3 -m http.server 8765), then NODE_PATH=$(npm root -g) node scripts/build-7.js.
// Writes docs/wip/abc-test-data-7.js: the ABC Test Org test data for all of PCF 7.0, loaded by docs/wip/abc_test_data_loader.html.
// Inputs: scripts/spec-7-2.js (the 24 hand-written 7.2 scenarios) and scripts/evidence-7-2.js (readiness evidence text).
// The other groups' scenarios are generated by rule with a fixed seed, so a rebuild gives the same set. Everything else
// (element grids, readiness records, step evidence) is built from the sandbox's own model, run headless.
const {chromium}=require('playwright'),fs=require('fs'),path=require('path');
const SPEC72=require('./spec-7-2.js'),EV=require('./evidence-7-2.js');
const OUT_FILE=path.join(__dirname,'..','docs','wip','abc-test-data-7.js');

// Seeded random numbers (mulberry32), so the set is the same on every rebuild.
let seed=70;const rnd=()=>{seed|=0;seed=seed+0x6D2B79F5|0;let t=Math.imul(seed^seed>>>15,1|seed);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};
const pick=a=>a[Math.floor(rnd()*a.length)],shuffle=a=>{a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(rnd()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;};
const ST=['Human-only','Judgment','Augmentation','Oversight','Agent-delegation','Automation'];
const ROLE_DIMS=['clarity','authority','skill','fluency','safety','capacity'],ORG_DIMS=['manager','governance','change','evidence'];

// One outcome per activity, in this order within each group (repeating for large groups), so every group shows
// each Readiness Gate outcome where it has enough activities.
const CYC=['clear','not_rd','ins_te','cond','top','none','not_te','rd_only','unassessed','te_only','cond_el','serious','ins_rd','override','past','clear','cond','top','not_rd','none','te_only','clear','ins_te','top'];
const SAY={clear:'The gate clears: every check is met or Ready.',cond:'Clears with conditions, each with its required action recorded.',cond_el:'Clears with conditions; one element is led past its own ceiling.',
 not_rd:'Holds: a role is Not Ready on one readiness dimension.',not_te:'Holds on the technical check: a measure misses its threshold.',serious:'Holds: the discrepancy log has an open Serious entry.',
 ins_te:'Holds on insufficient evidence: the technical check is below its minimum volume.',ins_rd:'Holds on insufficient evidence: one readiness dimension has no evidence yet.',
 rd_only:'Readiness assessed, the technical check not yet: the step holds gray.',te_only:'Technical check met, readiness not yet assessed: the step holds gray.',
 none:'Assessed, with nothing assessed for its next step yet (a dashed square).',top:'At its Progression Ceiling: no next step.',unassessed:'Unassessed: no Current State yet.',
 override:'A ceiling override raises the ceiling one step, with a review recorded.',past:'Past its Progression Ceiling with no override: a finding.'};
const OUT={clear:'Clears',cond:'Clears with conditions',cond_el:'Clears with conditions; element past its ceiling',not_rd:'Holds: Not Ready',not_te:'Holds: not met',serious:'Holds: not met',
 ins_te:'Holds: insufficient evidence',ins_rd:'Holds: insufficient evidence',rd_only:'Holds: insufficient evidence',te_only:'Holds: insufficient evidence',none:'Next step not yet assessed',
 top:'At its ceiling',unassessed:'Unassessed',override:'Ceiling override',past:'Past the ceiling'};
const EXPECT={clear:'clear',cond:'cond',cond_el:'cond',not_rd:'not',not_te:'not',serious:'not',ins_te:'ins',ins_rd:'ins',rd_only:'ins',te_only:'ins',none:'none',unassessed:'none',top:'TOP',override:'TOP',past:'TOP'};
const OUT72={'7.2.1.1':'Clears','7.2.1.2':'Holds: not met','7.2.1.3':'Holds: Not Ready','7.2.1.4':'At its ceiling','7.2.1.5':'Holds: insufficient evidence','7.2.1.6':'Unassessed','7.2.1.7':'Next step not yet assessed','7.2.2.1':'Ceiling override','7.2.2.2':'Past the ceiling','7.2.2.3':'Clears with conditions','7.2.2.4':'Clears with conditions; element past its ceiling','7.2.2.5':'Holds: insufficient evidence','7.2.2.6':'Holds: not met','7.2.3.1':'At its ceiling','7.2.3.2':'Clears','7.2.3.3':'Holds: insufficient evidence','7.2.3.4':'Clears with conditions','7.2.4.1':'Clears','7.2.4.2':'At its ceiling','7.2.4.3':'Holds: Not Ready','7.2.5.1':'Holds: not met','7.2.5.2':'At its ceiling','7.2.5.3':'Unassessed','7.2.5.4':'Holds: insufficient evidence'};

function fits(a,o){const c=a.ceil;
  if(o==='top'||o==='unassessed')return true;
  if(o==='override'||o==='past')return (a.cons==='Low'||a.cons==='Moderate')&&c<5&&(o==='past'||a.factors.length>0);
  if(o==='cond_el')return c>=3;
  return c>=1;}
function scenario(a,o){const conf=pick(['high','medium','medium','low']),ev=pick(['observed','system','audit','interview','document']),sp={conf,ev,say:SAY[o],o};
  const role=pick(a.roles),rdim=pick(ROLE_DIMS),odim=pick(ORG_DIMS.slice(0,3));
  if(o==='unassessed'){sp.cur=null;return sp;}
  if(o==='top'){sp.cur=ST[a.ceil];return sp;}
  if(o==='past'){sp.cur=ST[a.ceil+1];return sp;}
  if(o==='override'){sp.cur=ST[a.ceil+1];sp.override=true;sp.level=ST[a.ceil+1];return sp;}
  sp.cur=ST[o==='cond_el'?a.ceil-1:Math.floor(rnd()*a.ceil)];
  const over=a.over?{over:'ready'}:{};
  if(o==='clear'){sp.te={mode:'met'};sp.rd={base:'ready',...over};}
  if(o==='cond'||o==='cond_el'){sp.te={mode:'met'};sp.rd={base:'ready',set:{[rdim+'@'+role]:'cond',[odim]:'cond'},...(a.over?{over:rnd()<.5?'cond':'ready'}:{})};if(o==='cond_el')sp.elPast=true;}
  if(o==='not_rd'){sp.te={mode:rnd()<.5?'met':'none'};if(sp.te.mode==='none')delete sp.te;sp.rd={base:'ready',set:{[rdim+'@'+role]:'not'},...over};}
  if(o==='not_te'){sp.te={mode:'not',miss:0};sp.rd={base:'ready',...over};}
  if(o==='serious'){sp.te={mode:'serious'};sp.rd={base:'ready',...over};}
  if(o==='ins_te'){sp.te={mode:'ins'};sp.rd={base:'ready',...over};}
  if(o==='ins_rd'){sp.te={mode:'met'};sp.rd={base:'ready',set:{[pick(['evidence',rdim+'@'+role])]:'ins'},...over};}
  if(o==='rd_only'){sp.rd={base:'ready',...over};}
  if(o==='te_only'){sp.te={mode:'met'};}
  return sp;}

(async()=>{const b=await chromium.launch();const p=await b.newPage();
await p.route('**/*-api/**',r=>r.fulfill({status:200,contentType:'application/json',body:'{}'}));
await p.goto('http://localhost:8765/sandbox/pcf7.html');await p.waitForTimeout(2500);
const f=p.frames().find(x=>x.url().includes('four_views'));
const facts=await f.evaluate(()=>DATA.acts.map(a=>({code:a.code,name:a.name,cons:a.cons,ceil:rank(derivedCeil(a)),roles:rdRoles(a),factors:(P.FV_SOURCE.WR_DATA[a.code].ceilingFactors||[]),over:!!(rdOver(a)&&HC[a.cons])})).concat([{groups:DATA.groups}]));
const groups=facts.pop().groups,ACTS=facts;
const SPEC={},SCEN=[];
groups.forEach(([gc,gn])=>{const L=ACTS.filter(a=>a.code.startsWith(gc+'.'));
  if(gc==='7.2'){L.forEach(a=>{SPEC[a.code]=SPEC72[a.code];SCEN.push({code:a.code,name:a.name,group:gc,cur:SPEC72[a.code].cur,say:SPEC72[a.code].say,out:OUT72[a.code],exp:null});});return;}
  const free=shuffle(L),as={};
  CYC.concat(CYC).slice(0,L.length).forEach(o=>{const i=free.findIndex(a=>!as[a.code]&&fits(a,o));if(i>=0)as[free[i].code]=o;});
  L.forEach(a=>{if(!as[a.code])as[a.code]=a.ceil>=1?'none':'top';});
  L.forEach(a=>{const o=as[a.code],sp=scenario(a,o);SPEC[a.code]=sp;SCEN.push({code:a.code,name:a.name,group:gc,cur:sp.cur,say:sp.say,out:OUT[o],exp:EXPECT[o]});});});
// The payloads, built by the same code as the 7.2 set.
const BODY=fs.readFileSync(path.join(__dirname,'abc-payload-body.js'),'utf8');
const out=await f.evaluate(([SPEC,EV,BODY])=>new Function('SPEC','EV',BODY)(SPEC,EV),[SPEC,EV,BODY]);
const checks=out.checks;delete out.checks;
(out.noEl||[]).forEach(c=>{const x=SCEN.find(s=>s.code===c);x.out=OUT.cond;x.say=SAY.cond;});delete out.noEl;
const data=Object.assign({org:'abc-test-org',built:'2026-11-17',groups,scenarios:SCEN},out);
fs.writeFileSync(OUT_FILE,'// ABC Test Org test data for all of PCF 7.0 (Nov 17, 2026): one scenario per activity, so every group shows each input\n// and each Readiness Gate outcome where it has enough activities. Built by scripts/build-7.js; loaded by abc_test_data_loader.html.\nwindow.ABC_TEST_DATA = '+JSON.stringify(data)+';\n');
console.log('scenarios',SCEN.length,'assess',out.assess.length,'unassessed',out.del.length,'override',out.override.length,'ready',out.ready.length,'stepev',out.stepev.length);
console.log(checks.join('\n'));
const tally={};SCEN.forEach(s=>{tally[s.group]=tally[s.group]||{};tally[s.group][s.out]=(tally[s.group][s.out]||0)+1;});console.log(JSON.stringify(tally,null,0));
await b.close()})();
